CREATE OR REPLACE FUNCTION "app_private"."can_view_workflow_instance"("p_instance_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.wf_instance i
    where i.id = p_instance_id
      and (
        (select app_private.is_platform_super())
        or (
          (
            i.initiator_user_id = (select app_private.current_app_user_id())
