  insert into public.hr_compliance_event( entity_type, entity_id, event_type, from_status, to_status,
    actor_employee_id, comment, event_data
  ) values ( p_entity_type, p_entity_id, p_event_type, p_from_status, p_to_status,
    app_private.hr_current_employee_id(), nullif(btrim(p_comment), ''),
    coalesce(p_event_data, '{}'::jsonb)
  );
end
