--

--
-- Name: hr_find_leave_policy("uuid", "uuid", "date"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."hr_find_leave_policy"("p_employee_id" "uuid", "p_leave_type_id" "uuid", "p_effective_date" "date") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select policy_row.id
  from public.hr_leave_policy policy_row
  join public.hr_employee employee_row
    on employee_row.id = p_employee_id 
  left join lateral (
    select assignment_row.grade_id
    from public.hr_employee_assignment assignment_row
    where assignment_row.employee_id = employee_row.id
      
      and assignment_row.assignment_status = 'active'
      and assignment_row.effective_start <= p_effective_date
      and coalesce(assignment_row.effective_end, 'infinity'::date) >= p_effective_date
    order by assignment_row.primary_assignment desc, assignment_row.effective_start desc
    limit 1
  ) assignment_row on true
  where true
    and policy_row.leave_type_id = p_leave_type_id
    and policy_row.status = 'active'
    and policy_row.effective_from <= p_effective_date
    and coalesce(policy_row.effective_to, 'infinity'::date) >= p_effective_date
    and (
      policy_row.scope_type = 'all'
      or (policy_row.scope_type = 'organization' and policy_row.organization_id = employee_row.organization_id)
      or (policy_row.scope_type = 'employee' and policy_row.employee_id = employee_row.id)
      or (policy_row.scope_type = 'grade' and policy_row.grade_id = assignment_row.grade_id)
    )
  order by case policy_row.scope_type
    when 'employee' then 40 when 'organization' then 30 when 'grade' then 20 else 10 end desc,
    policy_row.effective_from desc
  limit 1;
$$;


ALTER FUNCTION "app_private"."hr_find_leave_policy"("p_employee_id" "uuid", "p_leave_type_id" "uuid", "p_effective_date" "date") OWNER TO "postgres";

--

--
-- Name: hr_get_employee_relation_case_detail_internal("uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."hr_get_employee_relation_case_detail_internal"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_case public.hr_employee_relation_case;
  v_result jsonb;
  v_sensitive boolean := app_private.is_platform_super()
    or app_private.has_permission('Hr:EmployeeRelations:Sensitive:View');
begin
  if not app_private.can_execute_business_action(
    'HrEmployeeRelations', 'Hr:EmployeeRelations:View', p_id, false
  ) then
    raise exception '当前账号没有查看员工关系案件的权限' using errcode = '42501';
  end if;
  select * into v_case from public.hr_employee_relation_case where id = p_id;
  if v_case.id is null or not app_private.hr_employee_relation_case_visible(v_case.subject_employee_id, v_case.reporter_employee_id,
    v_case.owner_employee_id
  ) then
    raise exception '员工关系案件不存在或无权查看' using errcode = '42501';
  end if;

  select (to_jsonb(v_case)
      - case when v_sensitive then '__none__' else 'allegation_summary' end
      - case when v_sensitive then '__none__' else 'findings_summary' end
      - case when v_sensitive then '__none__' else 'resolution_summary' end
      - case when v_sensitive then '__none__' else 'attachment_urls' end
      - case when v_sensitive then '__none__' else 'reporter_employee_id' end)
    || jsonb_build_object(
      'title', case when v_sensitive then v_case.title else '受限员工关系案件' end,
      'sensitive_restricted', not v_sensitive,
      'subject_employee', jsonb_build_object(
        'id', subject.id, 'employee_no', subject.employee_no,
        'employee_name', subject.employee_name, 'job_title', subject.job_title,
        'organization_name', organization.organization_name,
        'position_name', position.position_name
      ),
      'owner_employee', case when owner.id is null then null else jsonb_build_object(
        'id', owner.id, 'employee_no', owner.employee_no,
        'employee_name', owner.employee_name, 'job_title', owner.job_title
      ) end,
      'reporter_employee', case when not v_sensitive or v_case.anonymous_report
          or reporter.id is null then null else jsonb_build_object(
        'id', reporter.id, 'employee_no', reporter.employee_no,
        'employee_name', reporter.employee_name, 'job_title', reporter.job_title
      ) end,
      'actions', coalesce((
        select jsonb_agg(
          (to_jsonb(action)
            - case when v_sensitive then '__none__' else 'title' end
            - case when v_sensitive then '__none__' else 'completion_note' end
            - case when v_sensitive then '__none__' else 'remark' end)
          || jsonb_build_object(
            'title', case when v_sensitive then action.title else '受限处置行动' end,
            'owner_employee', jsonb_build_object(
              'id', action_owner.id, 'employee_no', action_owner.employee_no,
              'employee_name', action_owner.employee_name, 'job_title', action_owner.job_title
            )
          ) order by action.due_date, action.create_time
        )
        from public.hr_employee_relation_action action
        join public.hr_employee action_owner
          on action_owner.id = action.owner_employee_id
          
        where action.case_id = v_case.id 
      ), '[]'::jsonb),
      'events', coalesce((
        select jsonb_agg(
          (to_jsonb(event) - case when v_sensitive then '__none__' else 'comment' end)
          || jsonb_build_object(
            'actor', case when actor.id is null then null else jsonb_build_object(
              'id', actor.id, 'employee_no', actor.employee_no,
              'employee_name', actor.employee_name, 'job_title', actor.job_title
            ) end
          ) order by event.create_time desc
        )
        from public.hr_employee_relation_event event
        left join public.hr_employee actor
          on actor.id = event.actor_employee_id 
        where event.case_id = v_case.id 
      ), '[]'::jsonb)
    ) into v_result
  from public.hr_employee subject
  left join public.sys_organization organization on organization.id = subject.organization_id
  left join public.hr_position position on position.id = subject.position_id
  left join public.hr_employee owner
    on owner.id = v_case.owner_employee_id 
  left join public.hr_employee reporter
    on reporter.id = v_case.reporter_employee_id 
  where subject.id = v_case.subject_employee_id ;
  return v_result;
end
$$;


ALTER FUNCTION "app_private"."hr_get_employee_relation_case_detail_internal"("p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_guard_approval_record(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."hr_guard_approval_record"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if coalesce(current_setting('app.workflow_engine', true), '') = 'on' then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if old.status not in ('draft', 'rejected') then
      raise exception '当前状态的人事单据不可编辑';
    end if;
    if new.status is distinct from old.status then
      raise exception '人事单据状态只能通过审批流程变更';
    end if;
  elsif tg_op = 'DELETE' and old.status not in ('draft', 'rejected', 'cancelled') then
    raise exception '仅草稿、已驳回或已取消单据允许删除';
  end if;
  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "app_private"."hr_guard_approval_record"() OWNER TO "postgres";

--

--
-- Name: hr_list_employee_relations_records_internal("text", integer, integer, "text", "text", "text", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."hr_list_employee_relations_records_internal"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_case_type" "text" DEFAULT NULL::"text", "p_severity" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_sensitive boolean := app_private.is_platform_super()
    or app_private.has_permission('Hr:EmployeeRelations:Sensitive:View');
  v_offset integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(500,
    greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1));
  v_keyword text := nullif(btrim(p_keyword), '');
  v_result jsonb;
begin
  if p_kind not in ('case', 'action') then
    raise exception '不支持的员工关系记录类型';
  end if;
  if not app_private.can_execute_business_action(
    'HrEmployeeRelations', 'Hr:EmployeeRelations:View', null, false
  ) then
    raise exception '当前账号没有查看员工关系案件的权限' using errcode = '42501';
  end if;

  if p_kind = 'case' then
    with filtered as materialized (
      select relation_case.*,
        case when v_sensitive then relation_case.title else '受限员工关系案件' end as safe_title,
        jsonb_build_object(
          'id', subject.id, 'employee_no', subject.employee_no,
          'employee_name', subject.employee_name, 'job_title', subject.job_title,
          'organization_name', organization.organization_name,
          'position_name', position.position_name
        ) as subject_employee,
        case when owner.id is null then null else jsonb_build_object(
          'id', owner.id, 'employee_no', owner.employee_no,
          'employee_name', owner.employee_name, 'job_title', owner.job_title
        ) end as owner_employee,
        case when not v_sensitive or relation_case.anonymous_report or reporter.id is null then null
          else jsonb_build_object(
            'id', reporter.id, 'employee_no', reporter.employee_no,
            'employee_name', reporter.employee_name, 'job_title', reporter.job_title
          ) end as reporter_employee,
        (select count(*) from public.hr_employee_relation_action action
          where action.case_id = relation_case.id 
            and action.status in ('planned', 'in_progress')) as open_action_count,
        case
          when relation_case.status not in ('triaged', 'investigating', 'action_required')
            or relation_case.target_resolution_date is null then 'clear'
          when relation_case.target_resolution_date < current_date then 'overdue'
          when relation_case.target_resolution_date <= current_date + 7 then 'due_soon'
          else 'on_track'
        end as due_status
      from public.hr_employee_relation_case relation_case
      join public.hr_employee subject
        on subject.id = relation_case.subject_employee_id
        
      left join public.sys_organization organization on organization.id = subject.organization_id
      left join public.hr_position position on position.id = subject.position_id
      left join public.hr_employee owner
        on owner.id = relation_case.owner_employee_id 
      left join public.hr_employee reporter
        on reporter.id = relation_case.reporter_employee_id
        
      where true
        and app_private.hr_employee_relation_case_visible(relation_case.subject_employee_id,
          relation_case.reporter_employee_id, relation_case.owner_employee_id
        )
        and (p_status is null or relation_case.status = p_status)
        and (p_case_type is null or relation_case.case_type = p_case_type)
        and (p_severity is null or relation_case.severity = p_severity)
        and (
          v_keyword is null
          or relation_case.case_no ilike '%' || v_keyword || '%'
          or (v_sensitive and relation_case.title ilike '%' || v_keyword || '%')
          or subject.employee_no ilike '%' || v_keyword || '%'
          or subject.employee_name ilike '%' || v_keyword || '%'
          or owner.employee_name ilike '%' || v_keyword || '%'
        )
    ), paged as (
      select * from filtered
      order by
        case due_status when 'overdue' then 0 when 'due_soon' then 1 else 2 end,
        case severity when 'critical' then 0 when 'high' then 1 when 'medium' then 2 else 3 end,
        update_time desc
      offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged)
          - 'title' - 'allegation_summary' - 'findings_summary' - 'resolution_summary'
          - 'attachment_urls' - 'reporter_employee_id')
        || jsonb_build_object('title', paged.safe_title)
        order by
          case paged.due_status when 'overdue' then 0 when 'due_soon' then 1 else 2 end,
          case paged.severity when 'critical' then 0 when 'high' then 1
            when 'medium' then 2 else 3 end,
          paged.update_time desc
      ), '[]'::jsonb),
      'total', (select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
  end if;

  with filtered as materialized (
    select action.*,
      case when v_sensitive then action.title else '受限处置行动' end as safe_title,
      jsonb_build_object(
        'id', relation_case.id, 'case_no', relation_case.case_no,
        'title', case when v_sensitive then relation_case.title else '受限员工关系案件' end,
        'case_type', relation_case.case_type, 'status', relation_case.status,
        'severity', relation_case.severity
      ) as relation_case,
      jsonb_build_object(
        'id', owner.id, 'employee_no', owner.employee_no,
        'employee_name', owner.employee_name, 'job_title', owner.job_title
      ) as owner_employee,
      case
        when action.status not in ('planned', 'in_progress') then 'clear'
        when action.due_date < current_date then 'overdue'
        when action.due_date <= current_date + 7 then 'due_soon'
        else 'on_track'
      end as due_status
    from public.hr_employee_relation_action action
    join public.hr_employee_relation_case relation_case
      on relation_case.id = action.case_id 
    join public.hr_employee owner
      on owner.id = action.owner_employee_id 
    where true
      and app_private.hr_employee_relation_case_visible(relation_case.subject_employee_id,
        relation_case.reporter_employee_id, relation_case.owner_employee_id
      )
      and (p_status is null or action.status = p_status)
      and (p_case_type is null or relation_case.case_type = p_case_type)
      and (p_severity is null or relation_case.severity = p_severity)
      and (
        v_keyword is null
        or relation_case.case_no ilike '%' || v_keyword || '%'
        or (v_sensitive and action.title ilike '%' || v_keyword || '%')
        or owner.employee_no ilike '%' || v_keyword || '%'
        or owner.employee_name ilike '%' || v_keyword || '%'
      )
  ), paged as (
    select * from filtered
    order by case due_status when 'overdue' then 0 when 'due_soon' then 1 else 2 end,
      due_date, update_time desc
    offset v_offset limit v_limit
  )
  select jsonb_build_object(
    'records', coalesce(jsonb_agg(
      (to_jsonb(paged) - 'title' - 'completion_note' - 'remark')
        || jsonb_build_object('title', paged.safe_title)
      order by case paged.due_status when 'overdue' then 0
        when 'due_soon' then 1 else 2 end, paged.due_date, paged.update_time desc
    ), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into v_result from paged;
  return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
end
$$;


ALTER FUNCTION "app_private"."hr_list_employee_relations_records_internal"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_case_type" "text", "p_severity" "text") OWNER TO "postgres";

--

--
-- Name: hr_list_job_architecture_records_internal("text", integer, integer, "text", boolean); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."hr_list_job_architecture_records_internal"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_enabled" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_permission text;
  v_keyword text := nullif(btrim(coalesce(p_keyword, '')), '');
  v_offset integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer;
  v_result jsonb;
begin
  v_permission := case p_kind
    when 'family' then 'Hr:JobFamily:View'
    when 'grade' then 'Hr:Grade:View'
    when 'profile' then 'Hr:JobProfile:View'
    else null
  end;
  if v_permission is null then
    raise exception '不支持的职务体系记录类型' using errcode = '23514';
  end if;
  if not app_private.can_execute_business_action('HrJobArchitecture', v_permission, null, false) then
    raise exception '当前账号没有查看职务体系的权限' using errcode = '42501';
  end if;

  v_limit := least(2000, greatest(coalesce(p_to, 19) - v_offset + 1, 1));

  if p_kind = 'family' then
    v_result := (
      with filtered as materialized (
        select
          family_row.*,
          (
            select count(*)
            from public.mdm_job_profile profile_row
            where profile_row.family_id = family_row.id
          ) as job_profile_count
        from public.mdm_job_family family_row
        where true
          and (p_enabled is null or family_row.enabled = p_enabled)
          and (
            v_keyword is null
            or family_row.family_code ilike '%' || v_keyword || '%'
            or family_row.family_name ilike '%' || v_keyword || '%'
            or family_row.description ilike '%' || v_keyword || '%'
          )
      ),
      paged as (
        select *
        from filtered
        order by sort, family_name
        offset v_offset
        limit v_limit
      )
      select jsonb_build_object(
        'records', coalesce(
          (
            select jsonb_agg(to_jsonb(paged) order by paged.sort, paged.family_name)
            from paged
          ),
          '[]'::jsonb
        ),
        'total', (select count(*) from filtered)
      )
    );
    return v_result;
  end if;

  if p_kind = 'grade' then
    v_result := (
      with filtered as materialized (
        select
          grade_row.*,
          (
            select count(*)
            from public.mdm_job_profile profile_row
            where profile_row.default_grade_id = grade_row.id
          ) as job_profile_count
        from public.mdm_grade grade_row
        where true
          and (p_enabled is null or grade_row.enabled = p_enabled)
          and (
            v_keyword is null
            or grade_row.grade_code ilike '%' || v_keyword || '%'
            or grade_row.grade_name ilike '%' || v_keyword || '%'
            or grade_row.description ilike '%' || v_keyword || '%'
          )
      ),
      paged as (
        select *
        from filtered
        order by sort, grade_level, grade_name
        offset v_offset
        limit v_limit
      )
      select jsonb_build_object(
        'records', coalesce(
          (
            select jsonb_agg(to_jsonb(paged) order by paged.sort, paged.grade_level, paged.grade_name)
            from paged
          ),
          '[]'::jsonb
        ),
        'total', (select count(*) from filtered)
      )
    );
    return v_result;
  end if;

  v_result := (
    with filtered as materialized (
      select
        profile_row.*,
        family_row.family_code,
        family_row.family_name,
        grade_row.grade_code,
        grade_row.grade_name,
        (
          select count(*)
          from public.mdm_position position_row
          where position_row.job_profile_id = profile_row.id
        ) as position_count
      from public.mdm_job_profile profile_row
      join public.mdm_job_family family_row
        on family_row.id = profile_row.family_id
      left join public.mdm_grade grade_row
        on grade_row.id = profile_row.default_grade_id
      where true
        and (p_enabled is null or profile_row.enabled = p_enabled)
        and (
          v_keyword is null
          or profile_row.job_code ilike '%' || v_keyword || '%'
          or profile_row.job_name ilike '%' || v_keyword || '%'
          or profile_row.responsibilities ilike '%' || v_keyword || '%'
          or profile_row.requirements ilike '%' || v_keyword || '%'
          or profile_row.description ilike '%' || v_keyword || '%'
          or family_row.family_name ilike '%' || v_keyword || '%'
        )
    ),
    paged as (
      select *
      from filtered
      order by sort, job_name
      offset v_offset
      limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(
        (
          select jsonb_agg(
            (to_jsonb(paged) - 'family_code' - 'family_name' - 'grade_code' - 'grade_name')
            || jsonb_build_object(
              'family', jsonb_build_object(
                'id', paged.family_id,
                'family_code', paged.family_code,
                'family_name', paged.family_name
              ),
              'default_grade', case
                when paged.default_grade_id is null then null
                else jsonb_build_object(
                  'id', paged.default_grade_id,
                  'grade_code', paged.grade_code,
                  'grade_name', paged.grade_name
                )
              end
            )
            order by paged.sort, paged.job_name
          )
          from paged
        ),
        '[]'::jsonb
      ),
      'total', (select count(*) from filtered)
    )
  );
  return v_result;
end;
$$;


ALTER FUNCTION "app_private"."hr_list_job_architecture_records_internal"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_enabled" boolean) OWNER TO "postgres";

--

--
-- Name: hr_mask_external_email("text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."hr_mask_external_email"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when nullif(btrim(p_value), '') is null then null
    when strpos(btrim(p_value), '@') > 1
      then left(btrim(p_value), 1) || '***' || substring(btrim(p_value) from strpos(btrim(p_value), '@'))
    else '***'
  end;
$$;


ALTER FUNCTION "app_private"."hr_mask_external_email"("p_value" "text") OWNER TO "postgres";

--

--
-- Name: hr_mask_external_phone("text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."hr_mask_external_phone"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when nullif(btrim(p_value), '') is null then null
    when length(btrim(p_value)) >= 7
      then left(btrim(p_value), 3) || '****' || right(btrim(p_value), 4)
    else '***'
  end;
$$;


ALTER FUNCTION "app_private"."hr_mask_external_phone"("p_value" "text") OWNER TO "postgres";

--

--
-- Name: hr_save_job_architecture_record_internal("text", "uuid", "jsonb"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."hr_save_job_architecture_record_internal"("p_kind" "text", "p_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_permission text;
  v_code text;
  v_name text;
  v_enabled boolean := (p_payload ->> 'enabled')::boolean;
  v_sort integer := (p_payload ->> 'sort')::integer;
  v_description text := nullif(btrim(coalesce(p_payload ->> 'description', '')), '');
  v_level integer;
  v_family_id uuid;
  v_grade_id uuid;
  v_id uuid;
begin
  v_permission := case p_kind
    when 'family' then case when p_id is null then 'Hr:JobFamily:Add' else 'Hr:JobFamily:Edit' end
    when 'grade' then case when p_id is null then 'Hr:Grade:Add' else 'Hr:Grade:Edit' end
    when 'profile' then case when p_id is null then 'Hr:JobProfile:Add' else 'Hr:JobProfile:Edit' end
    else null
  end;
  if v_permission is null then
    raise exception '不支持的职务体系记录类型' using errcode = '23514';
  end if;
  if not app_private.can_execute_business_action('HrJobArchitecture', v_permission, null, false) then
    raise exception '当前账号没有维护职务体系的权限' using errcode = '42501';
  end if;

  if p_kind = 'family' then
    v_code := upper(btrim(coalesce(p_payload ->> 'family_code', '')));
    v_name := btrim(coalesce(p_payload ->> 'family_name', ''));
    if v_code = '' then raise exception '请输入职族编码' using errcode = '23514'; end if;
    if v_name = '' then raise exception '请输入职族名称' using errcode = '23514'; end if;

    if p_id is null then
      insert into public.mdm_job_family(family_code, family_name, enabled, sort, description)
      values (v_code, v_name, coalesce(v_enabled, true), coalesce(v_sort, 0), v_description)
      returning id into v_id;
    else
      update public.mdm_job_family
      set family_code = v_code,
          family_name = v_name,
          enabled = coalesce(v_enabled, enabled),
          sort = coalesce(v_sort, sort),
          description = v_description
      where id = p_id;
      if not found then raise exception '职族记录不存在或无权维护'; end if;
      v_id := p_id;
    end if;
    return v_id;
  end if;

  if p_kind = 'grade' then
    v_code := upper(btrim(coalesce(p_payload ->> 'grade_code', '')));
    v_name := btrim(coalesce(p_payload ->> 'grade_name', ''));
    v_level := coalesce((p_payload ->> 'grade_level')::integer, 1);
    if v_code = '' then raise exception '请输入职级编码' using errcode = '23514'; end if;
    if v_name = '' then raise exception '请输入职级名称' using errcode = '23514'; end if;
    if v_level < 1 then raise exception '层级值必须大于等于 1' using errcode = '23514'; end if;

    if p_id is null then
      insert into public.mdm_grade(grade_code, grade_name, grade_level, enabled, sort, description)
      values (v_code, v_name, v_level, coalesce(v_enabled, true), coalesce(v_sort, 0), v_description)
      returning id into v_id;
    else
      update public.mdm_grade
      set grade_code = v_code,
          grade_name = v_name,
          grade_level = v_level,
          enabled = coalesce(v_enabled, enabled),
          sort = coalesce(v_sort, sort),
          description = v_description
      where id = p_id;
      if not found then raise exception '职级记录不存在或无权维护'; end if;
      v_id := p_id;
    end if;
    return v_id;
  end if;

  v_code := upper(btrim(coalesce(p_payload ->> 'job_code', '')));
  v_name := btrim(coalesce(p_payload ->> 'job_name', ''));
  v_family_id := nullif(btrim(coalesce(p_payload ->> 'family_id', '')), '')::uuid;
  v_grade_id := nullif(btrim(coalesce(p_payload ->> 'default_grade_id', '')), '')::uuid;
  if v_code = '' then raise exception '请输入职务编码' using errcode = '23514'; end if;
  if v_name = '' then raise exception '请输入职务名称' using errcode = '23514'; end if;
  if v_family_id is null then raise exception '请选择所属职族' using errcode = '23514'; end if;
  if not exists (
    select 1 from public.mdm_job_family where id = v_family_id and enabled
  ) then
    raise exception '所选职族不存在或已停用' using errcode = '23514';
  end if;
  if v_grade_id is not null and not exists (
    select 1 from public.mdm_grade where id = v_grade_id and enabled
  ) then
    raise exception '所选职级不存在或已停用' using errcode = '23514';
  end if;

  if p_id is null then
    insert into public.mdm_job_profile(
      family_id, default_grade_id, job_code, job_name, enabled, sort,
      responsibilities, requirements, description
    )
    values (
      v_family_id, v_grade_id, v_code, v_name, coalesce(v_enabled, true), coalesce(v_sort, 0),
      nullif(btrim(coalesce(p_payload ->> 'responsibilities', '')), ''),
      nullif(btrim(coalesce(p_payload ->> 'requirements', '')), ''),
      v_description
    )
    returning id into v_id;
  else
    update public.mdm_job_profile
    set family_id = v_family_id,
        default_grade_id = v_grade_id,
        job_code = v_code,
        job_name = v_name,
        enabled = coalesce(v_enabled, enabled),
        sort = coalesce(v_sort, sort),
        responsibilities = nullif(btrim(coalesce(p_payload ->> 'responsibilities', '')), ''),
        requirements = nullif(btrim(coalesce(p_payload ->> 'requirements', '')), ''),
        description = v_description
    where id = p_id;
    if not found then raise exception '标准职务记录不存在或无权维护'; end if;
    v_id := p_id;
  end if;
  return v_id;
exception
  when unique_violation then
    if p_kind = 'family' then raise exception '职族编码或名称已存在' using errcode = '23505';
    elsif p_kind = 'grade' then raise exception '职级编码或名称已存在' using errcode = '23505';
    else raise exception '职务编码或名称已存在' using errcode = '23505';
    end if;
end;
$$;


ALTER FUNCTION "app_private"."hr_save_job_architecture_record_internal"("p_kind" "text", "p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

