--

CREATE OR REPLACE FUNCTION "app_private"."is_driver_user"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.sys_user u
    where u.auth_user_id = (select auth.uid())
      and u.status = '1'
      and u.deleted_at is null
      and u.user_type = '2'
  );
$$;


