--

--
-- Name: list_mdm_production_employees("uuid", integer, integer, "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."list_mdm_production_employees"("p_id" "uuid", "p_from" integer, "p_to" integer, "p_keyword" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
 contact boolean; identity boolean; payload jsonb;
begin
 if auth.uid() is null or not (
 app_private.has_permission('MdmProductionPersonnel:Add') or app_private.has_permission('MdmProductionPersonnel:Edit')
 or app_private.has_permission('MdmProductionPersonnel:View')) then
 raise exception '没有生产人员参选权限' using errcode='42501'; end if;
 contact:=app_private.has_permission('Hr:Employee:View') and app_private.resolve_field_access('hr.employee','contactDetails',null) in ('read','edit');
 identity:=app_private.has_permission('Hr:Employee:View') and app_private.resolve_field_access('hr.employee','identityDetails',null) in ('read','edit');
 with source as materialized (
  select e.id,e.employee_no,e.employee_name,e.avatar_url,e.job_title,e.employment_status,e.employment_type,
   case when contact then e.phone end as phone,case when identity then e.gender end as gender,
   e.hire_date,e.organization_id,o.organization_code,o.organization_name
  from public.mdm_employee e left join public.mdm_organization o on o.id=e.organization_id 
  where e.employment_status in ('active','probation') and (p_id is null or e.id=p_id)
  and (nullif(btrim(p_keyword),'') is null or e.employee_no ilike '%'||p_keyword||'%' or e.employee_name ilike '%'||p_keyword||'%' or e.job_title ilike '%'||p_keyword||'%')
 ), page as (select * from source order by employee_name,employee_no,id offset greatest(coalesce(p_from,0),0) limit least(greatest(coalesce(p_to,9)-greatest(coalesce(p_from,0),0)+1,1),200))
 select jsonb_build_object('total',(select count(*) from source),'records',coalesce((select jsonb_agg(jsonb_build_object(
 'id',p.id,'employee_no',p.employee_no,'employee_name',p.employee_name,
 'avatar_url',p.avatar_url,'job_title',p.job_title,'employment_status',p.employment_status,'employment_type',p.employment_type,
 'phone',p.phone,'gender',p.gender,'hire_date',p.hire_date,
 'organization',case when p.organization_id is null then null else jsonb_build_object('id',p.organization_id,'organization_code',p.organization_code,'organization_name',p.organization_name) end
 ) order by p.employee_name,p.employee_no,p.id) from page p),'[]'::jsonb),
 'field_access',jsonb_build_object('contactDetails',contact,'identityDetails',identity)) into payload;
 return payload;
end $$;


ALTER FUNCTION "app_private"."list_mdm_production_employees"("p_id" "uuid", "p_from" integer, "p_to" integer, "p_keyword" "text") OWNER TO "postgres";

--

--
-- Name: mark_header_notifications_read("text", "uuid"[]); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mark_header_notifications_read"("p_category" "text" DEFAULT NULL::"text", "p_notification_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select app_private.current_app_user_id());
  v_count integer;
begin
  if p_category is not null and p_category not in ('notice', 'message') then
    raise exception '待办事项需完成审批后自动归档';
  end if;

  update public.sys_notification n
  set is_read = true,
      read_at = coalesce(n.read_at, now())
  where true
    and n.recipient_user_id = v_user_id
    and n.category in ('notice', 'message')
    and n.is_read = false
    and (p_category is null or n.category = p_category)
    and (p_notification_ids is null or n.id = any(p_notification_ids));

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "app_private"."mark_header_notifications_read"("p_category" "text", "p_notification_ids" "uuid"[]) OWNER TO "postgres";

--

--
-- Name: mask_permission_value("text", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mask_permission_value"("p_value" "text", "p_strategy" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_length integer := char_length(coalesce(p_value, ''));
begin
  if p_value is null then
    return null;
  end if;

  return case p_strategy
    when 'phone' then
      case when v_length >= 7
        then left(p_value, 3) || repeat('*', greatest(v_length - 7, 4)) || right(p_value, 4)
        else repeat('*', greatest(v_length, 4))
      end
    when 'id_card' then
      case when v_length >= 8
        then left(p_value, 4) || repeat('*', v_length - 8) || right(p_value, 4)
        else repeat('*', greatest(v_length, 4))
      end
    when 'bank_account' then
      case when v_length >= 8
        then left(p_value, 4) || repeat('*', v_length - 8) || right(p_value, 4)
        else repeat('*', greatest(v_length, 4))
      end
    when 'address' then
      case when v_length > 6 then left(p_value, 6) || '***' else '***' end
    when 'amount' then '***'
    else '***'
  end;
end;
$$;


ALTER FUNCTION "app_private"."mask_permission_value"("p_value" "text", "p_strategy" "text") OWNER TO "postgres";

--

--
-- Name: mdm_add_work_center_devices("uuid", "uuid"[], "uuid", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_add_work_center_devices"("p_work_center_id" "uuid", "p_equipment_ids" "uuid"[], "p_main_equipment_id" "uuid" DEFAULT NULL::"uuid", "p_point" "text" DEFAULT '无'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_equipment_ids uuid[];
  v_inserted_count integer;
begin
  if auth.uid() is null
    or not app_private.has_permission('MdmWorkCenter:Devices')
  then
    raise exception '没有配置工作中心设备权限' using errcode = '42501';
  end if;

  perform 1 from public.mdm_work_center c where c.id = p_work_center_id;
  if not found then
    raise exception '工作中心不存在或不在当前工作范围内';
  end if;



  select coalesce(array_agg(distinct equipment_id), '{}'::uuid[])
    into v_equipment_ids
    from unnest(coalesce(p_equipment_ids, '{}'::uuid[])) as selected(equipment_id);

  if cardinality(v_equipment_ids) < 1 or cardinality(v_equipment_ids) > 100 then
    raise exception '请选择 1 至 100 台设备';
  end if;

  if p_point not in ('无', '投入点', '产出点') then
    raise exception '投入 / 产出点无效';
  end if;

  if p_main_equipment_id is not null
    and not (p_main_equipment_id = any(v_equipment_ids))
  then
    raise exception '主设备必须来自本次所选设备';
  end if;

  if p_main_equipment_id is not null
    and exists (
      select 1
        from public.mdm_work_center_device b
       where b.work_center_id = p_work_center_id
         and b.is_main
    )
  then
    raise exception '当前工作中心已经设置主设备';
  end if;

  if (
    select count(*)
      from public.mdm_equipment e
     where e.id = any(v_equipment_ids)
       and e.status = 'enabled'
       and not exists (
         select 1
           from public.mdm_work_center_device b
          where b.equipment_id = e.id
       )
  ) <> cardinality(v_equipment_ids)
  then
    raise exception '所选设备无效或已被其他工作中心关联';
  end if;

  insert into public.mdm_work_center_device (
    work_center_id,
    equipment_id,
    is_main,
    point
  )
  select
    p_work_center_id,
    equipment_id,
    equipment_id = p_main_equipment_id,
    p_point
  from unnest(v_equipment_ids) as selected(equipment_id);

  get diagnostics v_inserted_count = row_count;
  return v_inserted_count;
end
$$;


ALTER FUNCTION "app_private"."mdm_add_work_center_devices"("p_work_center_id" "uuid", "p_equipment_ids" "uuid"[], "p_main_equipment_id" "uuid", "p_point" "text") OWNER TO "postgres";

--

--
-- Name: mdm_convert_accessory_work_orders_internal("uuid"[], "jsonb"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_convert_accessory_work_orders_internal"("p_item_ids" "uuid"[], "p_config" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_item public.mdm_accessory_processing_item%rowtype;
  v_list public.mdm_accessory_processing_list%rowtype;
  v_project uuid := nullif(p_config->>'projectId','')::uuid;
  v_type uuid;
  v_order uuid;
  v_start date := coalesce(nullif(p_config->>'plannedStartDate','')::date,
    (now() at time zone 'Asia/Shanghai')::date);
  v_end date := nullif(p_config->>'plannedEndDate','')::date;
  v_construction text := nullif(btrim(p_config->>'constructionNo'),'');
  v_created integer := 0;
  v_skipped integer := 0;
begin
  if auth.uid() is null or not app_private.has_permission('MdmAccessoryProcessing:GenerateWorkOrder') then
    raise exception '当前账号没有转生产工单的权限' using errcode='42501';
  end if;
  if coalesce(array_length(p_item_ids,1),0) not between 1 and 100
     or jsonb_typeof(p_config)<>'object' then
    raise exception '请选择 1 至 100 个已生成物料的加工件' using errcode='22023';
  end if;
  if v_end is null or v_end<v_start then
    raise exception '计划完工日期不能早于计划开始日期' using errcode='22023';
  end if;
  if length(v_construction)>120 then
    raise exception '施工号不能超过 120 个字符' using errcode='22023';
  end if;
  for v_item in
    select * from public.mdm_accessory_processing_item
    where id=any(p_item_ids) order by list_id,line_no for update
  loop
    select * into v_list from public.mdm_accessory_processing_list
    where id=v_item.list_id for update;
    if v_type is null then
      select id into v_type from public.mdm_document_type
      where document_type_code='PP40' and enabled
      order by id limit 1;
      if v_type is null then
        raise exception '未启用 PP40 配件加工工单类型' using errcode='22023';
      end if;
    end if;
    if v_item.material_id is null then
      raise exception '第 % 个加工件尚未生成物料编码',v_item.line_no using errcode='22023';
    end if;
    if v_project is null then v_project := v_list.project_id; end if;
    if v_project is null or
       not exists(select 1 from public.mdm_project
         where id=v_project  and enabled) then
      raise exception '请先关联有效的系统项目' using errcode='22023';
    end if;
    if v_list.project_id is not null and v_list.project_id<>v_project then
      raise exception '所选加工件分属不同项目，请分别转单' using errcode='22023';
    end if;
    if v_list.project_id is null then
      update public.mdm_accessory_processing_list set project_id=v_project
      where id=v_list.id;
    end if;
    if exists(select 1 from public.mes_work_order
      where accessory_item_id=v_item.id and deleted_at is null) then
      v_skipped := v_skipped+1;
      continue;
    end if;
    if v_item.width_mm is null or v_item.width_mm <= 0 then
      raise exception '第 % 个加工件缺少展宽，请先删除编码并补齐展宽',v_item.line_no using errcode='22023';
    end if;
    insert into public.mes_work_order (work_order_no,work_order_type_id,project_id,construction_no,
      material_id,order_quantity,planned_start_date,planned_end_date,
      source,accessory_item_id,remark
    ) values ('',v_type,v_project,v_construction,v_item.material_id,v_item.quantity,
      v_start,v_end,'accessory_processing',v_item.id,
      left('配件加工清单：'||v_list.drawing_name||'；原表第'||v_item.row_no::text||'行',500)
    ) returning id into v_order;
    insert into public.mes_work_order_detail (work_order_id,area,number,length_mm,pieces,width_mm,
      area_sqm,remark,sort_order
    ) values (v_order,'',v_item.row_no::text,v_item.length_m*1000,v_item.quantity,
      v_item.width_mm,
      v_item.width_mm*v_item.length_m*v_item.quantity/1000,
      left(v_item.remark,500),10
    );
    v_created := v_created+1;
    if not exists(select 1 from public.mdm_accessory_processing_item i
      where i.list_id=v_item.list_id and not exists(
        select 1 from public.mes_work_order o
        where o.accessory_item_id=i.id and o.deleted_at is null
      )) then
      update public.mdm_accessory_processing_list set status='generated'
      where id=v_item.list_id;
    end if;
  end loop;
  if v_created+v_skipped <> cardinality(array(select distinct unnest(p_item_ids))) then
    raise exception '部分加工件不存在，请刷新后重试' using errcode='22023';
  end if;
  return jsonb_build_object('created',v_created,'skipped',v_skipped);
end
$$;


ALTER FUNCTION "app_private"."mdm_convert_accessory_work_orders_internal"("p_item_ids" "uuid"[], "p_config" "jsonb") OWNER TO "postgres";

--

--
-- Name: mdm_copy_process_route("uuid", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_copy_process_route"("p_id" "uuid", "p_name" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_source public.mdm_process_route%rowtype;
  v_target_id uuid;
  v_sequence record;
  v_step record;
  v_new_sequence_id uuid;
  v_new_step_id uuid;
  v_sequence_map jsonb := '{}'::jsonb;
  v_step_map jsonb := '{}'::jsonb;
  v_target_name text;
begin
  if auth.uid() is null or not app_private.has_permission('MdmProcessRoute:Copy') then
    raise exception '没有复制工艺路线权限' using errcode = '42501';
  end if;

  select * into strict v_source
  from public.mdm_process_route
  where id = p_id;


  v_target_name := coalesce(nullif(btrim(p_name), ''), v_source.name || ' - 副本');
  if char_length(v_target_name) > 200 then
    raise exception '路线名称不能超过 200 个字符' using errcode = '22023';
  end if;

  perform set_config('app.process_route_copy', '1', true);

  insert into public.mdm_process_route( material_id, name, code, route_type, allocation_mode, group_id,
    version, batch_from, batch_to, production_unit_id, department_id,
    effective_date, expiry_date, is_default, source, custom_unit_conversion,
    enabled, path, remark
  )
  values ( v_source.material_id, v_target_name, '',
    v_source.route_type, v_source.allocation_mode, v_source.group_id,
    v_source.version, v_source.batch_from, v_source.batch_to,
    v_source.production_unit_id, v_source.department_id,
    v_source.effective_date, v_source.expiry_date, false, 'copy',
    v_source.custom_unit_conversion, v_source.enabled, v_source.path, v_source.remark
  )
  returning id into v_target_id;

  delete from public.mdm_process_route_sequence
  where route_id = v_target_id;

  for v_sequence in
    select *
    from public.mdm_process_route_sequence
    where route_id = v_source.id
    order by sequence_no, id
  loop
    insert into public.mdm_process_route_sequence( route_id, sequence_no, sequence_type, remark
    )
    values ( v_target_id, v_sequence.sequence_no,
      v_sequence.sequence_type, v_sequence.remark
    )
    returning id into v_new_sequence_id;

    v_sequence_map := v_sequence_map ||
      jsonb_build_object(v_sequence.id::text, v_new_sequence_id::text);
  end loop;

  for v_step in
    select *
    from public.mdm_process_route_step
    where route_id = v_source.id
    order by sort, code, id
  loop
    insert into public.mdm_process_route_step( route_id, code, name, sort, work_center_id, work_center_ids,
      run_output_quantity, run_processing_minutes, run_green_minutes, setup_minutes,
      operator_count, machine_count, template_id, work_center_policy, config_updated_at,
      sequence_id, operation_id, description, unit_id, basic_batch, department_id,
      operation_mode, control_code_id, processing_mode, report_mode, inspection_mode,
      sequence_control, rework_mode, need_inspection, first_inspection,
      first_inspection_control, is_first, is_last, critical, unit_conversion,
      activities, outsourcing, inspection, sop_documents
    )
    values ( v_target_id, v_step.code, v_step.name, v_step.sort,
      v_step.work_center_id, v_step.work_center_ids, v_step.run_output_quantity,
      v_step.run_processing_minutes, v_step.run_green_minutes, v_step.setup_minutes,
      v_step.operator_count, v_step.machine_count, v_step.template_id,
      v_step.work_center_policy, v_step.config_updated_at,
      (v_sequence_map ->> v_step.sequence_id::text)::uuid,
      v_step.operation_id, v_step.description, v_step.unit_id, v_step.basic_batch,
      v_step.department_id, v_step.operation_mode, v_step.control_code_id,
      v_step.processing_mode, v_step.report_mode, v_step.inspection_mode,
      v_step.sequence_control, v_step.rework_mode, v_step.need_inspection,
      v_step.first_inspection, v_step.first_inspection_control,
      v_step.is_first, v_step.is_last, v_step.critical, v_step.unit_conversion,
      v_step.activities, v_step.outsourcing, v_step.inspection, v_step.sop_documents
    )
    returning id into v_new_step_id;

    v_step_map := v_step_map ||
      jsonb_build_object(v_step.id::text, v_new_step_id::text);
  end loop;

  for v_sequence in
    select *
    from public.mdm_process_route_sequence
    where route_id = v_source.id
  loop
    update public.mdm_process_route_sequence
    set
      transfer_in_step_id = case
        when v_sequence.transfer_in_step_id is null then null
        else (v_step_map ->> v_sequence.transfer_in_step_id::text)::uuid
      end,
      transfer_out_step_id = case
        when v_sequence.transfer_out_step_id is null then null
        else (v_step_map ->> v_sequence.transfer_out_step_id::text)::uuid
      end
    where id = (v_sequence_map ->> v_sequence.id::text)::uuid;
  end loop;

  perform set_config('app.process_route_copy', '0', true);
  return v_target_id;
end
$$;


ALTER FUNCTION "app_private"."mdm_copy_process_route"("p_id" "uuid", "p_name" "text") OWNER TO "postgres";

--

--
-- Name: mdm_current_actor_email(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_current_actor_email"() RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_email text;
begin
  select u.user_email
    into v_email
  from public.sys_user u
  where u.auth_user_id = (select auth.uid())
    and u.status = '1'
    and u.deleted_at is null;

  if nullif(btrim(v_email), '') is null then
    raise exception '当前业务账号邮箱不可用' using errcode = '42501';
  end if;
  return v_email;
end
$$;


ALTER FUNCTION "app_private"."mdm_current_actor_email"() OWNER TO "postgres";

--

--
-- Name: mdm_current_actor_user_id(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_current_actor_user_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid;
begin
  select u.id
    into v_user_id
  from public.sys_user u
  where u.auth_user_id = (select auth.uid())
    and u.status = '1'
    and u.deleted_at is null;

  if v_user_id is null then
    raise exception '当前业务账号不存在或已停用' using errcode = '42501';
  end if;
  return v_user_id;
end
$$;


