--

CREATE OR REPLACE FUNCTION "app_private"."tms_customer_option_to_secure_json"("p_customer" "public"."mdm_customer") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_secure jsonb := app_private.tms_customer_to_secure_json(p_customer, null);
begin
  return jsonb_strip_nulls(jsonb_build_object(
    'id', p_customer.id,
