--
-- Name: hr_organization_design_overview_secure(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_organization_design_overview_secure"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrOrganizationDesign','Hr:OrganizationDesign:View',null,false
  ) then raise exception '当前账号没有查看组织变革方案的权限' using errcode='42501'; end if;
  return jsonb_build_object(
    'draft_count',(select count(*) from public.hr_organization_design_scenario s where s.status in ('draft','rejected')),
    'review_count',(select count(*) from public.hr_organization_design_scenario s where s.status='impact_review'),
    'approved_count',(select count(*) from public.hr_organization_design_scenario s where s.status='approved'),
    'handoff_count',(select count(*) from public.hr_organization_design_scenario s where s.status='handed_off'),
    'high_risk_count',(select count(*) from public.hr_organization_design_scenario s where s.status not in ('cancelled','handed_off') and s.risk_level in ('high','critical')),
    'change_count',(select count(*) from public.hr_organization_design_change c join public.hr_organization_design_scenario s on s.id=c.scenario_id where s.status<>'cancelled'),
    'impacted_employee_count',(select coalesce(sum(c.impacted_employee_count),0) from public.hr_organization_design_change c join public.hr_organization_design_scenario s on s.id=c.scenario_id where s.status in ('impact_review','approved','handed_off')),
    'impacted_security_user_count',(select coalesce(sum(c.impacted_security_user_count),0) from public.hr_organization_design_change c join public.hr_organization_design_scenario s on s.id=c.scenario_id where s.status in ('impact_review','approved','handed_off'))
  );
end;
$$;


