    CONSTRAINT "hr_internal_opportunity_version_positive" CHECK (("version" > 0)),
    CONSTRAINT "hr_internal_opportunity_work_mode_check" CHECK (("work_mode" = ANY (ARRAY['onsite'::"text", 'hybrid'::"text", 'remote'::"text"])))
);


