    "organization_id" "uuid",
    "employee_id" "uuid",
    "grade_id" "uuid",
    "entitlement_method" "text" DEFAULT 'annual'::"text" NOT NULL,
    "annual_quota" numeric(10,2) DEFAULT 0 NOT NULL,
    "monthly_accrual" numeric(10,4) DEFAULT 0 NOT NULL,
    "carryover_limit" numeric(10,2) DEFAULT 0 NOT NULL,
    "carryover_expiry_months" integer,
    "allow_negative" boolean DEFAULT false NOT NULL,
    "negative_limit" numeric(10,2) DEFAULT 0 NOT NULL,
    "probation_eligible" boolean DEFAULT false NOT NULL,
    "effective_from" "date" NOT NULL,
    "effective_to" "date",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "description" "text",
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "hr_leave_policy_amounts_check" CHECK ((("annual_quota" >= (0)::numeric) AND ("monthly_accrual" >= (0)::numeric) AND ("carryover_limit" >= (0)::numeric) AND ("negative_limit" >= (0)::numeric))),
    CONSTRAINT "hr_leave_policy_carryover_expiry_check" CHECK ((("carryover_expiry_months" IS NULL) OR (("carryover_expiry_months" >= 1) AND ("carryover_expiry_months" <= 60)))),
    CONSTRAINT "hr_leave_policy_code_not_blank" CHECK (("btrim"("policy_code") <> ''::"text")),
    CONSTRAINT "hr_leave_policy_dates_check" CHECK ((("effective_to" IS NULL) OR ("effective_to" >= "effective_from"))),
    CONSTRAINT "hr_leave_policy_method_check" CHECK (("entitlement_method" = ANY (ARRAY['annual'::"text", 'monthly_accrual'::"text", 'manual'::"text", 'none'::"text"]))),
    CONSTRAINT "hr_leave_policy_name_not_blank" CHECK (("btrim"("policy_name") <> ''::"text")),
    CONSTRAINT "hr_leave_policy_scope_target_check" CHECK (((("scope_type" = 'all'::"text") AND ("organization_id" IS NULL) AND ("employee_id" IS NULL) AND ("grade_id" IS NULL)) OR (("scope_type" = 'organization'::"text") AND ("organization_id" IS NOT NULL) AND ("employee_id" IS NULL) AND ("grade_id" IS NULL)) OR (("scope_type" = 'employee'::"text") AND ("employee_id" IS NOT NULL) AND ("organization_id" IS NULL) AND ("grade_id" IS NULL)) OR (("scope_type" = 'grade'::"text") AND ("grade_id" IS NOT NULL) AND ("organization_id" IS NULL) AND ("employee_id" IS NULL)))),
    CONSTRAINT "hr_leave_policy_scope_type_check" CHECK (("scope_type" = ANY (ARRAY['all'::"text", 'organization'::"text", 'employee'::"text", 'grade'::"text"]))),
    CONSTRAINT "hr_leave_policy_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'inactive'::"text"])))
);


