    "submission_note" "text",
    "decision_note" "text",
    "baseline_captured_at" timestamp with time zone,
    "submitted_at" timestamp with time zone,
    "submitted_by" "text",
    "decided_at" timestamp with time zone,
    "decided_by" "text",
    "handed_off_at" timestamp with time zone,
    "handed_off_by" "text",
    "version" integer DEFAULT 1 NOT NULL,
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "hr_org_design_scenario_code_not_blank" CHECK (("btrim"("scenario_code") <> ''::"text")),
    CONSTRAINT "hr_org_design_scenario_decision_check" CHECK (((("status" = ANY (ARRAY['approved'::"text", 'rejected'::"text", 'handed_off'::"text"])) AND ("decided_at" IS NOT NULL) AND ("decided_by" IS NOT NULL) AND (NULLIF("btrim"("decision_note"), ''::"text") IS NOT NULL)) OR (("status" = ANY (ARRAY['draft'::"text", 'impact_review'::"text", 'cancelled'::"text"])) AND ("decided_at" IS NULL) AND ("decided_by" IS NULL)))),
    CONSTRAINT "hr_org_design_scenario_handoff_check" CHECK (((("status" = 'handed_off'::"text") AND ("handed_off_at" IS NOT NULL) AND ("handed_off_by" IS NOT NULL)) OR (("status" <> 'handed_off'::"text") AND ("handed_off_at" IS NULL) AND ("handed_off_by" IS NULL)))),
    CONSTRAINT "hr_org_design_scenario_name_not_blank" CHECK (("btrim"("scenario_name") <> ''::"text")),
    CONSTRAINT "hr_org_design_scenario_objective_not_blank" CHECK (("btrim"("objective") <> ''::"text")),
    CONSTRAINT "hr_org_design_scenario_risk_check" CHECK (("risk_level" = ANY (ARRAY['unassessed'::"text", 'low'::"text", 'medium'::"text", 'high'::"text", 'critical'::"text"]))),
    CONSTRAINT "hr_org_design_scenario_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'impact_review'::"text", 'approved'::"text", 'rejected'::"text", 'handed_off'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "hr_org_design_scenario_submission_check" CHECK (((("status" = ANY (ARRAY['impact_review'::"text", 'approved'::"text", 'rejected'::"text", 'handed_off'::"text"])) AND ("submitted_at" IS NOT NULL) AND ("submitted_by" IS NOT NULL) AND ("baseline_captured_at" IS NOT NULL)) OR (("status" = ANY (ARRAY['draft'::"text", 'cancelled'::"text"])) AND ("submitted_at" IS NULL) AND ("submitted_by" IS NULL)))),
    CONSTRAINT "hr_org_design_scenario_version_positive" CHECK (("version" > 0))
);


