--
-- Name: hr_policy_document; Type: TABLE; Schema: public
--

--

CREATE TABLE IF NOT EXISTS "public"."hr_policy_document" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "policy_code" "text" NOT NULL,
    "policy_title" "text" NOT NULL,
    "category" "text" NOT NULL,
    "version_no" integer DEFAULT 1 NOT NULL,
    "effective_date" "date" NOT NULL,
    "acknowledgement_due_days" integer DEFAULT 7 NOT NULL,
    "audience_type" "text" DEFAULT 'all'::"text" NOT NULL,
    "audience_organization_id" "uuid",
    "audience_employment_type" "text",
    "document_reference" "text" NOT NULL,
    "content_summary" "text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "supersedes_policy_id" "uuid",
    "published_at" timestamp with time zone,
    "published_by" "text",
    "retired_at" timestamp with time zone,
    "retired_by" "text",
    "decision_note" "text",
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "hr_policy_document_audience_scope_check" CHECK (((("audience_type" = 'all'::"text") AND ("audience_organization_id" IS NULL) AND ("audience_employment_type" IS NULL)) OR (("audience_type" = 'organization'::"text") AND ("audience_organization_id" IS NOT NULL) AND ("audience_employment_type" IS NULL)) OR (("audience_type" = 'employment_type'::"text") AND ("audience_organization_id" IS NULL) AND (NULLIF("btrim"("audience_employment_type"), ''::"text") IS NOT NULL)))),
    CONSTRAINT "hr_policy_document_audience_type_check" CHECK (("audience_type" = ANY (ARRAY['all'::"text", 'organization'::"text", 'employment_type'::"text"]))),
    CONSTRAINT "hr_policy_document_category_not_blank" CHECK (("btrim"("category") <> ''::"text")),
    CONSTRAINT "hr_policy_document_code_not_blank" CHECK (("btrim"("policy_code") <> ''::"text")),
    CONSTRAINT "hr_policy_document_due_days_check" CHECK ((("acknowledgement_due_days" >= 0) AND ("acknowledgement_due_days" <= 365))),
    CONSTRAINT "hr_policy_document_not_self_supersede" CHECK (("supersedes_policy_id" IS DISTINCT FROM "id")),
    CONSTRAINT "hr_policy_document_publish_check" CHECK (((("status" = ANY (ARRAY['published'::"text", 'retired'::"text"])) AND ("published_at" IS NOT NULL) AND ("published_by" IS NOT NULL)) OR (("status" = ANY (ARRAY['draft'::"text", 'cancelled'::"text"])) AND ("published_at" IS NULL) AND ("published_by" IS NULL)))),
    CONSTRAINT "hr_policy_document_reference_not_blank" CHECK (("btrim"("document_reference") <> ''::"text")),
    CONSTRAINT "hr_policy_document_retire_check" CHECK (((("status" = 'retired'::"text") AND ("retired_at" IS NOT NULL) AND ("retired_by" IS NOT NULL)) OR (("status" <> 'retired'::"text") AND ("retired_at" IS NULL) AND ("retired_by" IS NULL)))),
    CONSTRAINT "hr_policy_document_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'retired'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "hr_policy_document_summary_not_blank" CHECK (("btrim"("content_summary") <> ''::"text")),
    CONSTRAINT "hr_policy_document_title_not_blank" CHECK (("btrim"("policy_title") <> ''::"text")),
    CONSTRAINT "hr_policy_document_version_positive" CHECK (("version_no" > 0))
);


