    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "mdm_master_group_domain_check" CHECK (("domain" = ANY (ARRAY['customer'::"text", 'project'::"text", 'operation'::"text", 'process-route'::"text", 'warehouse'::"text", 'bom'::"text", 'component-type'::"text", 'supplier'::"text", 'material'::"text"])))
);


