--
-- Name: mdm_organization; Type: TABLE; Schema: public
--

--

CREATE TABLE IF NOT EXISTS "public"."mdm_organization" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "parent_id" "uuid",
    "organization_code" "text" NOT NULL,
    "organization_name" "text" NOT NULL,
    "organization_type" "text" DEFAULT 'department'::"text" NOT NULL,
    "leader_user_id" "uuid",
    "status" "text" DEFAULT '1'::"text" NOT NULL,
    "sort" integer DEFAULT 0 NOT NULL,
    "phone" "text",
    "email" "text",
    "address" "text",
    "description" "text",
    "is_system" boolean DEFAULT false NOT NULL,
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sys_organization_status_check" CHECK (("status" = ANY (ARRAY['0'::"text", '1'::"text"]))),
    CONSTRAINT "sys_organization_system_root_check" CHECK (((NOT "is_system") OR (("parent_id" IS NULL) AND ("organization_code" = 'ROOT'::"text") AND ("organization_type" = 'company'::"text") AND ("status" = '1'::"text")))),
    CONSTRAINT "sys_organization_type_check" CHECK (("organization_type" = ANY (ARRAY['company'::"text", 'division'::"text", 'department'::"text", 'team'::"text"])))
);


