    CONSTRAINT "sys_user_account_identity_link_check" CHECK (((("account_identity_type" = 'employee'::"text") AND ("hr_employee_id" IS NOT NULL)) OR (("account_identity_type" = ANY (ARRAY['external'::"text", 'service'::"text", 'platform'::"text", 'pending_review'::"text"])) AND ("hr_employee_id" IS NULL)))),
    CONSTRAINT "sys_user_account_identity_type_check" CHECK (("account_identity_type" = ANY (ARRAY['employee'::"text", 'external'::"text", 'service'::"text", 'platform'::"text", 'pending_review'::"text"]))),
    CONSTRAINT "sys_user_soft_delete_audit_check" CHECK ((("deleted_at" IS NULL) = ("deleted_by" IS NULL))),
    CONSTRAINT "sys_user_status_check" CHECK (("status" = ANY (ARRAY['1'::"text", '2'::"text"])))
);


