--
-- Name: mdm_customer accessory_processing_customer_read; Type: POLICY; Schema: public
--

DROP POLICY IF EXISTS "accessory_processing_customer_read" ON "public"."mdm_customer";
--

CREATE POLICY "accessory_processing_customer_read" ON "public"."mdm_customer" FOR SELECT TO "authenticated" USING ("app_private"."has_permission"('MdmAccessoryProcessing:SaveDraft'::"text"));


--

--
-- Name: mdm_master_group authenticated_select; Type: POLICY; Schema: public
--

DROP POLICY IF EXISTS "authenticated_select" ON "public"."mdm_master_group";
--

CREATE POLICY "authenticated_select" ON "public"."mdm_master_group" FOR SELECT TO "authenticated" USING ((true AND
CASE "domain"
    WHEN 'customer'::"text" THEN ( SELECT "app_private"."has_permission"('MdmSalesCustomer:View'::"text") AS "has_permission")
    WHEN 'project'::"text" THEN ( SELECT "app_private"."has_permission"('MdmSalesProject:View'::"text") AS "has_permission")
    WHEN 'operation'::"text" THEN ( SELECT "app_private"."has_permission"('MdmOperationSet:View'::"text") AS "has_permission")
    WHEN 'process-route'::"text" THEN ( SELECT "app_private"."has_permission"('MdmProcessRoute:View'::"text") AS "has_permission")
    WHEN 'warehouse'::"text" THEN ( SELECT "app_private"."has_permission"('MdmWarehouseDefinition:View'::"text") AS "has_permission")
    ELSE false
END));


--

--
-- Name: sys_user authenticated_select; Type: POLICY; Schema: public
--

DROP POLICY IF EXISTS "authenticated_select" ON "public"."sys_user";
--

CREATE POLICY "authenticated_select" ON "public"."sys_user" FOR SELECT TO "authenticated" USING (
CASE
    WHEN ("auth_user_id" = ( SELECT "auth"."uid"() AS "uid")) THEN true
    ELSE true
END);


--

--
-- Name: mdm_master_group bom_group_select; Type: POLICY; Schema: public
--

DROP POLICY IF EXISTS "bom_group_select" ON "public"."mdm_master_group";
--

CREATE POLICY "bom_group_select" ON "public"."mdm_master_group" FOR SELECT TO "authenticated" USING ((("domain" = 'bom'::"text") AND true AND (( SELECT "app_private"."is_platform_super"() AS "is_platform_super") OR ( SELECT "app_private"."has_permission"('MdmBomMaintenance:View'::"text") AS "has_permission") OR ( SELECT "app_private"."has_permission"('MdmBomStructure:View'::"text") AS "has_permission"))));


