--

--
-- Name: mdm_master_group mdm_master_group_delete_authorized; Type: POLICY; Schema: public
--

DROP POLICY IF EXISTS "mdm_master_group_delete_authorized" ON "public"."mdm_master_group";
--

CREATE POLICY "mdm_master_group_delete_authorized" ON "public"."mdm_master_group" FOR DELETE TO "authenticated" USING (("app_private"."is_platform_super"() OR
CASE "domain"
    WHEN 'customer'::"text" THEN "app_private"."has_permission"('MdmSalesCustomer:ManageGroup'::"text")
    WHEN 'project'::"text" THEN "app_private"."has_permission"('MdmSalesProject:ManageGroup'::"text")
    WHEN 'operation'::"text" THEN "app_private"."has_permission"('MdmOperationSet:ManageGroup'::"text")
    ELSE false
END));


--

--
-- Name: mdm_master_group mdm_master_group_insert_authorized; Type: POLICY; Schema: public
--

DROP POLICY IF EXISTS "mdm_master_group_insert_authorized" ON "public"."mdm_master_group";
--

CREATE POLICY "mdm_master_group_insert_authorized" ON "public"."mdm_master_group" FOR INSERT TO "authenticated" WITH CHECK (("app_private"."is_platform_super"() OR
CASE "domain"
    WHEN 'customer'::"text" THEN "app_private"."has_permission"('MdmSalesCustomer:ManageGroup'::"text")
    WHEN 'project'::"text" THEN "app_private"."has_permission"('MdmSalesProject:ManageGroup'::"text")
    WHEN 'operation'::"text" THEN "app_private"."has_permission"('MdmOperationSet:ManageGroup'::"text")
    ELSE false
END));


--

--
-- Name: mdm_master_group mdm_master_group_update_authorized; Type: POLICY; Schema: public
--

DROP POLICY IF EXISTS "mdm_master_group_update_authorized" ON "public"."mdm_master_group";
--

CREATE POLICY "mdm_master_group_update_authorized" ON "public"."mdm_master_group" FOR UPDATE TO "authenticated" USING (("app_private"."is_platform_super"() OR
CASE "domain"
    WHEN 'customer'::"text" THEN "app_private"."has_permission"('MdmSalesCustomer:ManageGroup'::"text")
    WHEN 'project'::"text" THEN "app_private"."has_permission"('MdmSalesProject:ManageGroup'::"text")
    WHEN 'operation'::"text" THEN "app_private"."has_permission"('MdmOperationSet:ManageGroup'::"text")
    ELSE false
END)) WITH CHECK (("app_private"."is_platform_super"() OR
CASE "domain"
    WHEN 'customer'::"text" THEN "app_private"."has_permission"('MdmSalesCustomer:ManageGroup'::"text")
    WHEN 'project'::"text" THEN "app_private"."has_permission"('MdmSalesProject:ManageGroup'::"text")
    WHEN 'operation'::"text" THEN "app_private"."has_permission"('MdmOperationSet:ManageGroup'::"text")
    ELSE false
END));


